/**
 * The resource library catalogue: which of the owner's files belong
 * together, and what each one is.
 *
 * Only titles and file names live here. The repository is public and the
 * resources are the owner's copyright, so their content — text, images,
 * slides, speaker notes, the search index — is generated by
 * `scripts/library/build.ts` and kept in private Blob storage, never in git.
 *
 * Adding a resource: put the files in `resources/`, add an entry below, then
 * run the build and upload scripts (docs/library.md). A file that is in
 * `resources/` but not listed here is reported by the build, so nothing the
 * owner sends is silently left out.
 */

import { WORKSHEET_5_KEY } from "@/lib/forms/library";

export type SeriesKey = "getting-started" | "worksheets" | "act" | "relationships";

export type MaterialKind =
  | "practitioner-guide"
  | "presentation"
  | "learning-guide"
  | "activity-worksheet"
  | "review-form";

export type Series = {
  key: SeriesKey;
  title: string;
  /** Singular label used with a collection's number, e.g. "Worksheet 5". */
  unit: string | null;
  blurb: string;
};

export type CatalogueMaterial = {
  /** Unique within its collection; used in the URL. */
  id: string;
  kind: MaterialKind;
  /** File name in `resources/`. */
  file: string;
  /** Overrides the kind's label where a collection has two of a kind. */
  title?: string;
  /** A short qualifier from the document itself, e.g. "50-minute session outline". */
  subtitle?: string;
};

export type CatalogueCollection = {
  /** Used in the URL. Never change one that is live: links to it would break. */
  slug: string;
  series: SeriesKey;
  number: number | null;
  title: string;
  /** Other titles the materials use for the same resource, so search finds them. */
  aliases?: string[];
  materials: CatalogueMaterial[];
  /** The online version a client can complete in their portal, where one exists. */
  onlineWorksheetKey?: string;
};

