/** Order on the page and in a collection: prepare, teach, explain, practise. */
export const MATERIAL_KINDS: { kind: MaterialKind; label: string; plural: string; step: string }[] = [
  { kind: "practitioner-guide", label: "Practitioner guide", plural: "Practitioner guides", step: "Prepare" },
  { kind: "presentation", label: "Teaching presentation", plural: "Teaching presentations", step: "Teach" },
  { kind: "learning-guide", label: "Client learning guide", plural: "Client learning guides", step: "Explain" },
  { kind: "activity-worksheet", label: "Client activity worksheet", plural: "Client activity worksheets", step: "Practise" },
  { kind: "review-form", label: "Review & agreed support form", plural: "Review forms", step: "Record" },
];

const four = (
  files: { guide: string; slides: string; learning: string; activity: string },
  extra: Partial<Record<"guide" | "slides" | "learning" | "activity", string>> = {}
): CatalogueMaterial[] => [
  { id: "practitioner-guide", kind: "practitioner-guide", file: files.guide, subtitle: extra.guide },
  { id: "presentation", kind: "presentation", file: files.slides, subtitle: extra.slides },
  { id: "learning-guide", kind: "learning-guide", file: files.learning, subtitle: extra.learning },
  { id: "activity-worksheet", kind: "activity-worksheet", file: files.activity, subtitle: extra.activity },
];

