/**
 * Files in `resources/` deliberately left out, with the reason. The build
 * warns about anything neither catalogued nor listed here.
 */
export const IGNORED_FILES: Record<string, string> = {
  "ThriveSphere_Client_Learning_Guide_With_Original_Images (1).docx":
    "Byte-for-byte copy of the ACT Resource 1 learning guide.",
};

export function seriesFor(key: SeriesKey): Series {
  const s = SERIES.find((x) => x.key === key);
  if (!s) throw new Error(`Unknown series ${key}`);
  return s;
}

export function kindMeta(kind: MaterialKind) {
  const m = MATERIAL_KINDS.find((k) => k.kind === kind);
  if (!m) throw new Error(`Unknown material kind ${kind}`);
  return m;
}

/** "Worksheet 5", "ACT resource 2", or null for an unnumbered collection. */
export function collectionLabel(c: { series: SeriesKey; number: number | null }): string | null {
  const unit = seriesFor(c.series).unit;
  return unit && c.number != null ? `${unit} ${c.number}` : null;
}

export function materialTitle(m: Pick<CatalogueMaterial, "kind" | "title">): string {
  return m.title ?? kindMeta(m.kind).label;
}
